{
  "flashcards": [
    {
      "front": "What is the primary benefit of using TypeScript in a large React codebase?",
      "back": "It provides static type checking, which catches bugs at compile-time rather than runtime, improves developer experience via better IDE autocompletion, and makes refactoring safer and more predictable.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "How do you ensure a React component is accessible according to WCAG standards?",
      "back": "Use semantic HTML elements, manage focus states correctly, ensure sufficient color contrast, provide alt text for images, and use ARIA labels only when semantic HTML is insufficient.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the main purpose of a design system?",
      "back": "To provide a single source of truth for design patterns, UI components, and brand guidelines, ensuring consistency, scalability, and efficiency across multiple products and teams.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is the difference between a component library and a design system?",
      "back": "A component library is a collection of reusable UI code. A design system includes the library but also encompasses design tokens, documentation, accessibility guidelines, and usage principles.",
      "requirement_ids": ["r4", "r5"]
    },
    {
      "front": "How do you handle disagreements with designers regarding component implementation?",
      "back": "Focus on user impact and technical feasibility. Propose compromises that maintain the design intent while adhering to accessibility standards and performance constraints, framing the discussion around shared goals.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "When should you use Server-Side Rendering (SSR) in Next.js?",
      "back": "Use SSR when you need data to be fresh for every request, or when SEO is critical for dynamic content that cannot be statically generated at build time.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is the core philosophy of React Testing Library?",
      "back": "The more your tests resemble the way your software is used, the more confidence they can give you. It encourages testing user behavior rather than implementation details.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "What is the primary use case for Playwright in a React project?",
      "back": "End-to-end testing. It simulates real user interactions across multiple browsers and devices to verify critical user flows and ensure the application works as expected in production-like environments.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "What are React 'Prop Types' and why are they largely replaced by TypeScript?",
      "back": "Prop Types provide runtime type checking for component props. TypeScript replaces them by providing compile-time checking, which is more robust, catches errors earlier, and offers better tooling support.",
      "requirement_ids": ["r1", "r2"]
    },
    {
      "front": "How do you manage focus in a custom React modal component?",
      "back": "Implement focus trapping: when the modal opens, move focus to the first interactive element. When it closes, return focus to the element that triggered it.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the benefit of using 'Static Site Generation' (SSG) in Next.js?",
      "back": "It generates HTML at build time, resulting in extremely fast page loads and reduced server load, as the content is served as static files via a CDN.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "How do you test a component that relies on an API call using Testing Library?",
      "back": "Mock the API module or use a tool like MSW (Mock Service Worker) to intercept requests, ensuring the test remains deterministic and fast without hitting real endpoints.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "What is the 'Single Responsibility Principle' in the context of React components?",
      "back": "A component should ideally do one thing. If it grows too large or handles too many concerns, it should be decomposed into smaller, reusable sub-components.",
      "requirement_ids": ["r1", "r5"]
    },
    {
      "front": "How do you ensure your design system components are accessible to screen readers?",
      "back": "Use appropriate ARIA roles, ensure keyboard navigability, maintain a logical tab order, and test components using screen readers like NVDA or VoiceOver during development.",
      "requirement_ids": ["r3", "r4"]
    }
  ]
}
